import sys,random,networkx as nx
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from fastgen import fast_generate
from testgen import cuts_ok
random.seed(6060)
for n in range(2,13):
 for it in range(800):
  G=nx.DiGraph();G.add_nodes_from(range(n))
  for u in range(n):
   for v in range(n):
