  roots={i:random.choice([0,0,1,2,3,5]) for i in range(n)}
  if sum(roots.values())==0:roots[random.randrange(n)]=1
  ok,_=cuts_ok(G,roots)
  if not ok:continue
  try:Ts,Cs=fast_generate(G,list(range(n)),roots)
  except Exception as e:
   print('FAIL',n,it,roots,sorted(G.edges(data=True)),repr(e));raise
  agg={}
  for (r,i),T in Ts.items():
   if len(T)!=n-1 or len(set(T))!=n-1:raise Exception('shape')
   for a,b in T:agg[(a,b)]=agg.get((a,b),0)+Cs[(r,i)]
  for (a,b),c in agg.items():assert c<=G[a][b]['capacity']
  for u,c in roots.items():assert sum(v for (r,i),v in Cs.items() if r==u)==c
 print(n,'ok')
print('FAST RANDOM OK')
